```python
def get_valid_input():
    """Get valid arithmetic input from user."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            operator = input("Enter the operator (+, -, *, /): ").upper()
            num2 = float(input("Enter the second number: "))

            if operator not in ['+', '-', '*', '/']:
                raise ValueError("Invalid operator. Please use +, -, *, or /.")

            return num1, operator, num2
        except ValueError as e:
            print(e)

def perform_operation(num1, operator, num2):
    """Perform arithmetic operation and return result."""
    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operator. Please use +, -, *, or /.")

    return result

def main():
    num1, operator, num2 = get_valid_input()

    try:
        result = perform_operation(num1, operator, num2)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```

This program defines three functions: `get_valid_input()` to get valid arithmetic input from the user, `perform_operation()` to perform the arithmetic operation, and `main()` to call the other two functions and handle any errors.
